SELECT ?name ?point ?timeseriesId WHERE {
  ?p a brick:ElectricPower .
  ?p rdfs:label ?name .
  ?p ref:hasTimeseriesId ?timeseriesId .
}

SELECT ?point ?class WHERE {
  ?point a ?class .
  ?point rdfs:label ?name .
  FILTER(?name IN ("Chiller02","CondPump01","CondPump02"))
}

SELECT ?s ?class WHERE {
  ?s ref:#ifcName ?name .
  FILTER(?name IN ("Chiller02","CondPump01","CondPump02"))
  ?s a ?class
}

SELECT ?entity ?class ?name WHERE {
  ?entity brick:hasExternalReference ?ref .
  ?ref <https://brickschema.org/schema/Brick/ref#ifcName> ?name .
  FILTER(?name IN ("Chiller02","CondPump01","CondPump02"))
  ?entity a ?class .
}

